<?php
if (!defined('ABSPATH')) { exit; }
global $wpdb; $products=SPF_Database::table('products'); $lots=SPF_Database::table('lots'); $product_count=(int)$wpdb->get_var("SELECT COUNT(*) FROM $products WHERE status='active'"); $stock_units=(int)$wpdb->get_var("SELECT COALESCE(SUM(l.quantity),0) FROM $lots l INNER JOIN $products p ON p.id=l.product_id WHERE p.status='active'"); $country=SPF_Config::country();
?>
<div class="wrap spf-wrap"><h1><?php esc_html_e('Sistema para Farmacias','sistema-para-farmacias'); ?></h1><div class="spf-cards"><div class="spf-card"><strong><?php echo esc_html($product_count); ?></strong><span><?php esc_html_e('Productos activos','sistema-para-farmacias'); ?></span></div><div class="spf-card"><strong><?php echo esc_html($stock_units); ?></strong><span><?php esc_html_e('Unidades en stock','sistema-para-farmacias'); ?></span></div><div class="spf-card"><strong><?php echo esc_html($country['name']); ?></strong><span><?php esc_html_e('País operativo','sistema-para-farmacias'); ?></span></div><div class="spf-card"><strong><?php echo esc_html(SPF_Config::tax_name().' '.SPF_Config::tax_rate().'%'); ?></strong><span><?php esc_html_e('Impuesto principal','sistema-para-farmacias'); ?></span></div></div><div class="spf-panel"><h2><?php esc_html_e('Migración funcional','sistema-para-farmacias'); ?></h2><p><?php esc_html_e('Productos e Inventario/Lotes ya funcionan sobre el nuevo núcleo multi-país y reutilizan los datos históricos de FarmaPOS cuando existen.','sistema-para-farmacias'); ?></p></div></div>
